type JourneyMission={id:string;journey_id:string;family_id:string;source_mission_id:string|null;title:string;description:string;instructions:string;category:string;skills:string[];estimated_minutes:number;xp_reward:number;evidence_types:string[];phase:number;mission_order:number;recommendation_reasons:string[];is_custom:boolean;why_this_mission?:string;effort_weight:number;progress_percentage:number;contextualized_micro_lesson?:string;contextualized_steps?:string[];contextualized_evidence_request?:string};
