  useEffect(()=>{load()},[load]);
  const save=async(m:JourneyMission)=>{const original=items.find(x=>x.id===m.id);const substantial=Boolean(original&&(original.description.trim()!==m.description.trim()||original.instructions.trim()!==m.instructions.trim()));const parentCustom=Boolean(original?.is_custom||substantial);const update:any={title:m.title,description:m.description,instructions:m.instructions,estimated_minutes:m.estimated_minutes,xp_reward:m.xp_reward,skills:m.skills,evidence_types:m.evidence_types,effort_weight:m.effort_weight,is_custom:parentCustom,updated_at:new Date().toISOString()};if(substantial)Object.assign(update,{contextualized_intro:null,contextualized_micro_lesson:null,contextualized_steps:null,contextualized_evidence_request:null,follow_up_question:null,why_this_mission:null,technique_explanation:null,contextualized_example:null,autonomy_guidance:null,parent_support_guidance:null,reflection_depth:null,evidence_checklist:null});const{error}=await supabase.from('journey_missions').update(update).eq('id',m.id);if(error)setMessage(friendlyError(error,'Não foi possível salvar a missão. Tente novamente.'));else{setEditing(null);setMessage(substantial?'Missão transformada em personalizada. Progresso recalculado.':'Missão salva com o conteúdo KONKI preservado. Progresso recalculado.');load()}};
