function Notifications(){const[items,setItems]=useState<any[]>([]);const load=()=>supabase.from('notifications').select('*').order('created_at',{ascending:false}).limit(30).then(({data})=>setItems(data||[]));useEffect(()=>{load()},[]);const read=async(id:string)=>{await supabase.rpc('mark_notification_read',{target_notification:id});load()};return <><Header over="CENTRAL" title="Notificações" text="O que pede atenção e o que já avançou."/><div className="notification-list">{items.map(n=><button key={n.id} className={n.read_at?'read':''} onClick={()=>read(n.id)}><i/><span><b>{n.title}</b><small>{n.message}</small></span></button>)}</div></>}

