function PilotNotifications({go}:{go:Go}){const[items,setItems]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[message,setMessage]=useState('');const load=useCallback(async()=>{setLoading(true);setError('');const result=await supabase.from('notifications').select('*').order('created_at',{ascending:false}).limit(30);if(result.error)setError('Não conseguimos carregar suas notificações.');else setItems(result.data||[]);setLoading(false)},[]);useEffect(()=>{load()},[load]);const open=async(n:any)=>{setMessage('');if(!n.read_at){const read=await supabase.rpc('mark_notification_read',{target_notification:n.id});if(read.error)return setMessage('Não foi possível marcar a notificação como lida. Tente novamente.')}const target=notificationRoute(n);go(target.view,{assignmentId:target.assignmentId,contractId:target.contractId})};return <><Header over="CENTRAL" title="Notificações" text="O que pede atenção e o que já avançou."/>{loading?<LoadingState label="Carregando notificações…"/>:error?<RetryState message={error} onRetry={load}/>:items.length?<div className="notification-list">{items.map(n=><button key={n.id} className={n.read_at?'read':''} onClick={()=>open(n)}><i/><span><b>{n.title}</b><small>{n.message}</small></span></button>)}</div>:<section className="empty-card"><p>Nenhuma notificação por aqui.</p></section>}{message&&<Alert>{message}</Alert>}</>}

function Passport({profile}:{profile:Profile}){const[xp,setXp]=useState(0),[done,setDone]=useState<any[]>([]);useEffect(()=>{supabase.from('youth_profiles').select('total_xp').eq('profile_id',profile.id).maybeSingle().then(({data})=>setXp(data?.total_xp||0));supabase.from('mission_assignments').select('approved_at,mission:missions(title,skills)').eq('status','APPROVED').order('approved_at',{ascending:false}).then(({data})=>setDone(data||[]))},[profile.id]);const all=useMemo(()=>done.flatMap(x=>(x.mission as any).skills||[]),[done]);return <><Header over="SUA HISTÓRIA" title="Passaporte" text="Evidências reais do que você já colocou em prática."/><section className="passport-head"><div className="passport-avatar">{profile.first_name[0]}</div><div><h2>{profile.first_name}</h2><p>{xp} XP · {done.length} missões verificadas</p></div><Mark/></section><h2 className="subheading">Habilidades praticadas</h2><div className="choice-grid">{[...new Set(all)].map(x=><span className="skill-chip" key={x}>{x}</span>)}</div><h2 className="subheading">Trajetória</h2>{done.map((x:any)=><div className="timeline-item" key={x.approved_at}><i>✓</i><span><b>{x.mission.title}</b><small>{new Date(x.approved_at).toLocaleDateString('pt-BR')}</small></span></div>)}</>}
function ParentInvite({family}:{family:Family}){const[token,setToken]=useState(''),[code,setCode]=useState(family.invite_code),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{supabase.from('family_invites').select('link_token,code').eq('family_id',family.id).is('claimed_at',null).order('created_at',{ascending:false}).limit(1).maybeSingle().then(({data})=>{setToken(data?.link_token||'');setCode(data?.code||family.invite_code)})},[family.id,family.invite_code]);const link=token&&typeof location!=='undefined'?`${location.origin}/invite/${token}`:'';const copy=async(value:string,label:string)=>{await navigator.clipboard.writeText(value);setMessage(label)};const create=async()=>{setBusy(true);setMessage('');const{data}=await supabase.auth.getSession();const response=await fetch('/api/auth/family-invites',{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${data.session?.access_token}`},body:JSON.stringify({familyId:family.id})}),body=await response.json() as{error?:string;linkToken?:string;code?:string};setBusy(false);if(!response.ok||!body.linkToken)return setMessage(body.error||'Não foi possível criar o convite.');setToken(body.linkToken);setCode(body.code||'');setMessage('Novo convite criado.')};const share=async()=>{if(!link)return;if(navigator.share){try{await navigator.share({title:'Convite KONKI',text:'Entre na nossa família na KONKI.',url:link});setMessage('Convite compartilhado.');return}catch{}}await copy(link,'Link copiado.')};return <section className="panel invite-panel"><h2>Convide alguém da família</h2><p>O convidado escolhe se entra como responsável ou jovem. Cada link pode ser usado uma vez.</p>{link?<div className="action-row"><button className="primary" onClick={()=>copy(link,'Link copiado.')}>Copiar link</button><button className="secondary" onClick={share}>Compartilhar</button></div>:<Alert>O último convite já foi usado. Gere outro para adicionar uma pessoa.</Alert>}<button className="secondary wide" disabled={busy} onClick={create}>{busy?'Gerando…':link?'Gerar outro convite':'Gerar novo convite'}</button>{code&&<div className="invite"><span>Ou use o código para jovem</span><button onClick={()=>copy(code,'Código copiado.')}><b>{code}</b></button></div>}{message&&<Alert kind={message.includes('criado')||message.includes('copiado')||message.includes('compartilhado')?'success':'error'}>{message}</Alert>}</section>}
function ProfileScreen({profile,family,logout}:{profile:Profile;family:Family|null;logout:()=>void}){return <><Header over="SUA CONTA" title={profile.first_name} text={`${roleLabel(profile.role)} · ${family?.name||'KONKI'}`}/>{profile.role==='PARENT'&&family&&<ParentInvite family={family}/>}<ThemeControl/><section className="panel"><h2>Privacidade</h2><p>Seus dados, conquistas e evidências são privados e isolados por família.</p><button className="secondary wide" onClick={logout}>Sair</button></section></>}
function Admin(){const[data,setData]=useState<any>(null),[error,setError]=useState('');useEffect(()=>{supabase.auth.getSession().then(async({data:s})=>{const r=await fetch('/api/admin/overview',{headers:{authorization:`Bearer ${s.session?.access_token}`}});const j=await r.json() as ApiResponse;if(r.ok)setData(j);else setError(j.error||'Não foi possível carregar a visão administrativa.')})},[]);return <><Header over="ADMIN" title="Operação KONKI" text="Métricas agregadas sem expor evidências privadas."/>{error&&<Alert>{error}</Alert>}{data&&<><div className="admin-grid">{Object.entries(data.metrics||{}).map(([k,v])=><div key={k}><b>{String(v)}</b><small>{k.replaceAll('_',' ')}</small></div>)}</div><section className="panel"><h2>Funil</h2>{Object.entries(data.funnel||{}).map(([k,v])=><div className="status-line" key={k}><span>{k}</span><b>{String(v)}</b></div>)}</section></>}</>}
function Header({over,title,text}:{over:string;title:string;text:string}){return <header className="page-title"><span>{over}</span><h1>{title}</h1><p>{text}</p></header>}
function Nav({role,active,go}:{role:Role;active:View;go:(v:View)=>void}){const items:[View,string,string][] = role==='PARENT'?[['home','Início','⌂'],['conquest','Conquista','◇'],['review','Revisar','✓'],['contract','Contrato','▤'],['profile','Perfil','○']]:[['home','Início','⌂'],['missions','Missões','✓'],['conquest','Conquista','◇'],['passport','Passaporte','▤'],['profile','Perfil','○']];return <nav className="bottom-nav">{items.map(([v,l,i])=><button key={v} className={active===v?'active':''} onClick={()=>go(v)}><i>{i}</i><span>{l}</span></button>)}</nav>}
